/** Dispatch a built-in brush id to its generated factory. Returns false when
 * `id` is not a built-in (the caller falls through to the extras registry).
 * The two neighbor sources are template parameters, not literals: the mesh
 * executor passes CsrNbr/LiveDiskNbr, the grid executor its own GridCsrNbr.
 * A @fulltopo kernel always takes NbrLive — its pre-pass thaws topology, so
 * a stroke-start CSR snapshot would go stale under it. */
template <CommandTypes TYPES,
          sculptcore::brush::NbrSource NbrCsr,
          sculptcore::brush::NbrSource NbrLive,
          sculptcore::brush::AccumMode AccMode>
inline bool createBuiltinBrush(int id, bool csrNeighbors,
                               BrushCommandDef<CommandCtx<TYPES>> &def)
{
  switch (id) {
  case 0: // DRAW
    createDrawBrush<TYPES, AccMode>(def);
    return true;
  case 1: // INFLATE
    createInflateBrush<TYPES, AccMode>(def);
    return true;
  case 2: // CLAY
  case 10: // SCRAPE
  case 11: // FILL
    createPlaneBrush<TYPES, AccMode>(def);
    return true;
  case 3: // PINCH
    createPinchBrush<TYPES, AccMode>(def);
    return true;
  case 4: // SHARP
    createSharpBrush<TYPES, AccMode>(def);
    return true;
  case 5: // MASK
    createMaskBrush<TYPES, AccMode>(def);
    return true;
  case 6: // SMOOTH
    if (csrNeighbors) {
      createSmoothBrush<TYPES, NbrCsr, AccMode>(def);
    } else {
      createSmoothBrush<TYPES, NbrLive, AccMode>(def);
    }
    return true;
  case 7: // KELVINLET
    createKelvinletBrush<TYPES, AccMode>(def);
    return true;
  case 8: // POSE
    createPoseBrush<TYPES, AccMode>(def);
    return true;
  case 9: // TEXDRAW
    createTexdrawBrush<TYPES, AccMode>(def);
    return true;
  case 12: // WINGSCRAPE
    createWingscrapeBrush<TYPES, AccMode>(def);
    return true;
  case 13: // COLOR
    createColorBrush<TYPES, AccMode>(def);
    return true;
  case 14: // POLYGROUP
    createPolygroupBrush<TYPES, AccMode>(def);
    return true;
  case 15: // BSMOOTH
    if (csrNeighbors) {
      createBsmoothBrush<TYPES, NbrCsr, AccMode>(def);
    } else {
      createBsmoothBrush<TYPES, NbrLive, AccMode>(def);
    }
    return true;
  case 16: // GRAB
    createGrabBrush<TYPES, AccMode>(def);
    return true;
  case 17: // SNAKEHOOK
    createSnakehookBrush<TYPES, AccMode>(def);
    return true;
  case 18: // COLORSMOOTH
    if (csrNeighbors) {
      createColorsmoothBrush<TYPES, NbrCsr, AccMode>(def);
    } else {
      createColorsmoothBrush<TYPES, NbrLive, AccMode>(def);
    }
    return true;
  case 19: // FEATURE_ALIGN
    createFeaturealignBrush<TYPES, NbrLive, AccMode>(def);
    return true;
  case 20: // LAYERDRAW
    createLayerdrawBrush<TYPES, AccMode>(def);
    return true;
  case 21: // ENHANCE
    createEnhanceBrush<TYPES, AccMode>(def);
    return true;
  case 22: // TEXGRAD
    createTexgradBrush<TYPES, AccMode>(def);
    return true;
  default:
    return false;
  }
}

